/**
 * 群聊「接话」判定表（纯本地，零 token）。
 *
 * 官方 QQ 机器人默认只在被 @ 时处理群消息（config.requireMention）。群管理开启
 * 「接收所有消息」后每条群消息都会推到网关，但仍要决定「这条要不要跑一轮模型」
 * ——跑一轮就是一次 token。所有判定都在这里，只用时间戳和字符串匹配，不调模型。
 *
 * 配置：~/.dsh/qq-bot-pro/settings.json 的 gate 段（改完 2 秒内生效）。
 * 每条规则都能单独关：answerAll / replyToName / replyToQuote / replyToFollowUp /
 * skipWhenMentioningOthers / mergeBurst。
 */
import { readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

const spoken = new Map();   // 'group:<openid>' -> 她最后说话时间
const answered = new Map(); // 'group:<openid>:<senderId>' -> 上次放行时间（连发合并用）

const SETTINGS_FILE = join(homedir(), '.dsh', 'qq-bot-pro', 'settings.json');
const LEGACY_GATE_FILE = join(homedir(), '.dsh', 'qq-bot-pro', 'gate.json');
const DEFAULT_GATE = {
    answerAll: false,                 // 群里谁说话都接（会花 token：每条约一轮）；默认关，见 settings.json
    replyToName: true,                // 有人叫她名字就接
    replyToQuote: true,               // 引用她的话就接
    replyToFollowUp: true,            // 她刚说完话，接着说的话就接
    skipWhenMentioningOthers: true,   // @ 了别人时不插嘴
    mergeBurst: true,                 // 同一个人连发只接第一句
    nameHints: ['小肥鱼', '肥鱼', '鲸鱼', '小鱼'],
    followWindowMs: 5 * 60 * 1000,
    quoteWindowMs: 15 * 60 * 1000,
    burstMs: 2500
};

let cache = { at: 0, value: DEFAULT_GATE };
function readJson(file) {
    try {
        const raw = JSON.parse(readFileSync(file, 'utf8'));
        return raw && typeof raw === 'object' ? raw : undefined;
    }
    catch {
        return undefined;
    }
}
function gateConfig() {
    const now = Date.now();
    if (now - cache.at < 2000)
        return cache.value;
    const settings = readJson(SETTINGS_FILE);
    const gate = (settings && typeof settings.gate === 'object' && settings.gate)
        ? settings.gate
        : (readJson(LEGACY_GATE_FILE) ?? {});
    cache = { at: now, value: { ...DEFAULT_GATE, ...gate } };
    return cache.value;
}

function keyOf(target) {
    if (!target || !target.scope || !target.targetId)
        return undefined;
    return String(target.scope) + ':' + String(target.targetId);
}

/** 记一次「她在这个会话说过话」。 */
export function markBotSpoke(target, at = Date.now()) {
    const key = keyOf(target);
    if (!key)
        return;
    spoken.set(key, at);
}

/** 她最后一次在这个会话说话的时间戳（没有则 0）。 */
export function lastBotSpoke(target) {
    return spoken.get(keyOf(target)) ?? 0;
}

/**
 * 隐式 @：群里没 @ 她、但这条消息该接。
 * 命中顺序：叫她名字 → 引用她 → 接着她的话 → answerAll。
 * 每次命中都把原因写到 ctx.state.spokeReason，便于日志核对。
 */
export function isImplicitMention(ctx) {
    try {
        const msg = ctx && ctx.message;
        if (!msg || msg.kind !== 'group' || !msg.groupOpenid)
            return false;
        if (msg.senderIsBot)
            return false;
        const cfg = gateConfig();
        const mentions = msg.mentions;
        if (cfg.skipWhenMentioningOthers !== false && Array.isArray(mentions) && mentions.length > 0 && !mentions.some((m) => m && m.is_you === true))
            return false;
        const key = 'group:' + String(msg.groupOpenid);
        const who = key + ':' + String(msg.senderId || '');
        const now = Date.now();
        const text = String(msg.content || '');
        const prev = answered.get(who) ?? 0;
        const burst = cfg.mergeBurst !== false && now - prev < (cfg.burstMs ?? 2500);
        const pass = (reason) => {
            if (ctx.state)
                ctx.state.spokeReason = reason;
            answered.set(who, now);
            return true;
        };
        const hit = (reason) => (burst ? false : pass(reason));
        if (cfg.replyToName !== false && (cfg.nameHints || []).some((h) => h && text.includes(String(h))))
            return hit('name');
        const last = spoken.get(key) ?? 0;
        const quote = ctx.state && ctx.state.quote;
        const quoted = Boolean(quote && (quote.text || quote.rawContent));
        if (cfg.replyToQuote !== false && quoted && last && now - last <= (cfg.quoteWindowMs ?? 900000))
            return hit('quote');
        if (cfg.replyToFollowUp !== false && last && now - last <= (cfg.followWindowMs ?? 300000))
            return hit('follow');
        if (cfg.answerAll !== false)
            return hit('all');
        return false;
    }
    catch {
        return false;
    }
}
